const LOUIZE_REGULAR = "data:font/opentype;base64,";
const LOUIZE_ITALIC = "data:font/opentype;base64,";
const EDITORIAL_METHOD = "data:font/opentype;base64,";

const BOOKS_ILLUSTRATION = "data:image/png;base64,";
const FORMATS = ["Paperback", "Hardcover", "Ebook", "Audiobook"];
const READ_STATUSES = ["Read", "Unread"];
const OWNERS = ["Hers", "His"];
const STATUS_COLORS = { Unread: "#83715B", Read: "#83715B" };
const SPINE_COLORS = ["#93A8B3", "#96A97C", "#C98977", "#CE9A3E", "#A98FAE", "#8FA8A0"];

function uid() {
  return (crypto.randomUUID ? crypto.randomUUID() : Date.now() + "-" + Math.random().toString(36).slice(2));
}

function spineColorFor(str) {
  let hash = 0;
  for (let i = 0; i < (str || "").length; i++) hash = str.charCodeAt(i) + ((hash << 5) - hash);
  return SPINE_COLORS[Math.abs(hash) % SPINE_COLORS.length];
}

function todayISO() {
  return new Date().toISOString().slice(0, 10);
}

function resizeImageFile(file, maxDim = 640, quality = 0.82) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const img = new Image();
      img.onload = () => {
        let { width, height } = img;
        if (width > height && width > maxDim) {
          height = Math.round(height * (maxDim / width));
          width = maxDim;
        } else if (height >= width && height > maxDim) {
          width = Math.round(width * (maxDim / height));
          height = maxDim;
        }
        const canvas = document.createElement("canvas");
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL("image/jpeg", quality));
      };
      img.onerror = () => reject(new Error("Couldn't read that image"));
      img.src = reader.result;
    };
    reader.onerror = () => reject(new Error("Couldn't read that file"));
    reader.readAsDataURL(file);
  });
}

async function fetchBookData(isbnRaw) {
  const isbn = isbnRaw.replace(/[^0-9Xx]/g, "");
  if (!isbn) return null;

  // Try Open Library first — free, no API key, CORS-enabled.
  try {
    const olRes = await fetch(
      `https://openlibrary.org/api/books?bibkeys=ISBN:${isbn}&format=json&jscmd=data`
    );
    if (olRes.ok) {
      const olData = await olRes.json();
      const book = olData[`ISBN:${isbn}`];
      if (book && book.title) {
        return {
          title: book.title || "",
          author: (book.authors || []).map((a) => a.name).join(", "),
          totalPages: book.number_of_pages || "",
          genres: (book.subjects || []).slice(0, 4).map((s) => s.name),
          coverUrl:
            (book.cover && (book.cover.large || book.cover.medium)) ||
            `https://covers.openlibrary.org/b/isbn/${isbn}-L.jpg`,
        };
      }
    }
  } catch (e) { /* fall through to Google Books */ }

  // Fallback: Google Books — also free, no key needed for basic lookups.
  try {
    const gbRes = await fetch(
      `https://www.googleapis.com/books/v1/volumes?q=isbn:${isbn}`
    );
    if (gbRes.ok) {
      const gbData = await gbRes.json();
      const item = gbData.items && gbData.items[0];
      const vi = item && item.volumeInfo;
      if (vi && vi.title) {
        return {
          title: vi.title || "",
          author: (vi.authors || []).join(", "),
          totalPages: vi.pageCount || "",
          genres: (vi.categories || []).slice(0, 4),
          coverUrl:
            (vi.imageLinks && (vi.imageLinks.thumbnail || vi.imageLinks.smallThumbnail) || "").replace(
              "http://",
              "https://"
            ) || `https://covers.openlibrary.org/b/isbn/${isbn}-L.jpg`,
        };
      }
    }
  } catch (e) { /* nothing found */ }

  return null;
}

