/* ---------- small building blocks ---------- */

function StarRating({ value, onChange, readOnly, size = 18 }) {
  return (
    <div style={{ display: "flex", gap: 2 }}>
      {[1, 2, 3, 4, 5].map((n) => (
        <button
          key={n}
          type="button"
          disabled={readOnly}
          onClick={() => onChange && onChange(n === value ? 0 : n)}
          style={{
            background: "none",
            border: "none",
            padding: 0,
            cursor: readOnly ? "default" : "pointer",
            lineHeight: 0,
          }}
          aria-label={`${n} star`}
        >
          <Star
            size={size}
            color="#83715B"
            fill={n <= value ? "#83715B" : "none"}
            strokeWidth={1.5}
          />
        </button>
      ))}
    </div>
  );
}

function TagInput({ value, onChange, placeholder }) {
  const [draft, setDraft] = useState("");
  const commit = () => {
    const t = draft.trim();
    if (t && !value.includes(t)) onChange([...value, t]);
    setDraft("");
  };
  return (
    <div className="tag-input">
      {value.map((t, i) => (
        <span key={i} className="chip">
          {t}
          <button type="button" onClick={() => onChange(value.filter((_, idx) => idx !== i))}>
            <X size={11} />
          </button>
        </span>
      ))}
      <input
        value={draft}
        placeholder={placeholder}
        onChange={(e) => setDraft(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === ",") {
            e.preventDefault();
            commit();
          } else if (e.key === "Backspace" && !draft && value.length) {
            onChange(value.slice(0, -1));
          }
        }}
        onBlur={commit}
      />
    </div>
  );
}

function BookCover({ book, size = "normal" }) {
  const dims =
    size === "small" ? { w: 44, h: 64 } :
    size === "detail" ? { w: 132, h: "auto" } :
    { w: "100%", h: "auto" };
  if (book.coverUrl) {
    return (
      <img
        src={book.coverUrl}
        alt={book.title}
        style={{ width: dims.w, aspectRatio: "2/3", objectFit: "cover", borderRadius: 3, display: "block" }}
        onError={(e) => { e.target.style.display = "none"; }}
      />
    );
  }
  return (
    <div
      style={{
        width: dims.w,
        aspectRatio: "2/3",
        borderRadius: 3,
        background: spineColorFor(book.title || book.isbn),
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        padding: 6,
        textAlign: "center",
      }}
    >
      <span style={{ color: "#fff", fontFamily: "'Louize', serif", fontSize: size === "small" ? 9 : 13, lineHeight: 1.15, fontWeight: 600 }}>
        {book.title || "Untitled"}
      </span>
    </div>
  );
}

/* ---------- camera barcode scanner ---------- */

function CameraScanner({ onDetected, onManualFallback, onClose }) {
  const videoRef = useRef(null);
  const readerRef = useRef(null);
  const [error, setError] = useState("");
  const [starting, setStarting] = useState(true);

  useEffect(() => {
    let cancelled = false;

    (async () => {
      try {
        const { BrowserMultiFormatReader } = await import("@zxing/browser");
        const reader = new BrowserMultiFormatReader();
        readerRef.current = reader;

        const controls = await reader.decodeFromConstraints(
          { video: { facingMode: "environment" } },
          videoRef.current,
          (result) => {
            if (result && !cancelled) {
              const text = result.getText();
              // book barcodes are EAN-13 (ISBN-13); keep digits only
              const digits = text.replace(/[^0-9]/g, "");
              if (digits.length >= 9) {
                controls.stop();
                onDetected(digits);
              }
            }
          }
        );
        readerRef.current._controls = controls;
        if (!cancelled) setStarting(false);
      } catch (e) {
        if (!cancelled) {
          setStarting(false);
          setError(
            e && e.name === "NotAllowedError"
              ? "Camera access was denied. You can still enter the ISBN by hand below."
              : "Couldn't start the camera on this device. You can still enter the ISBN by hand below."
          );
        }
      }
    })();

    return () => {
      cancelled = true;
      try {
        readerRef.current && readerRef.current._controls && readerRef.current._controls.stop();
      } catch (e) { /* ignore */ }
    };
  }, [onDetected]);

  return (
    <div className="scan-panel">
      <div className="scan-video-wrap quagga-target">
        <video ref={videoRef} muted playsInline style={{ width: "100%", borderRadius: 10, background: "#111" }} />
        {!error && <div className="scan-line" />}
      </div>
      {starting && !error && <p className="scan-hint">Starting camera…</p>}
      {!starting && !error && <p className="scan-hint">Point your camera at the barcode on the back of the book</p>}
      {error && (
        <div className="scan-fallback-note">
          <AlertCircle size={15} color="#8A5A2E" style={{ flexShrink: 0, marginTop: 1 }} />
          <span>{error}</span>
        </div>
      )}
      <button className="btn-text" onClick={onManualFallback}>Type the ISBN instead</button>
      <button className="btn-text" onClick={onClose}>Cancel</button>
    </div>
  );
}

