function BookForm({ initial, onSave, onCancel, isEditing }) {
  const [book, setBook] = useState(initial);
  const [coverBusy, setCoverBusy] = useState(false);
  const [coverError, setCoverError] = useState("");
  const set = (patch) => setBook((b) => ({ ...b, ...patch }));

  const handleCoverFile = async (e) => {
    const file = e.target.files && e.target.files[0];
    e.target.value = "";
    if (!file) return;
    setCoverError("");
    setCoverBusy(true);
    try {
      const dataUrl = await resizeImageFile(file);
      set({ coverUrl: dataUrl });
    } catch (err) {
      setCoverError("Couldn't use that photo — try a different one.");
    } finally {
      setCoverBusy(false);
    }
  };

  return (
    <div className="form-card">
      <div className="form-cover-row">
        <div>
          <BookCover book={book} />
          <label htmlFor="cover-upload" className="cover-upload-btn">
            {coverBusy ? "Adding..." : book.coverUrl ? "Change photo" : "Add cover photo"}
          </label>
          <input
            id="cover-upload"
            type="file"
            accept="image/*"
            onChange={handleCoverFile}
            style={{ display: "none" }}
          />
          {book.coverUrl && (
            <button type="button" className="cover-remove-btn" onClick={() => set({ coverUrl: "" })}>
              Remove
            </button>
          )}
          {coverError && <p className="cover-error">{coverError}</p>}
        </div>
        <div style={{ flex: 1 }}>
          <label>Title</label>
          <input value={book.title} onChange={(e) => set({ title: e.target.value })} placeholder="Book title" />
          <label>Author</label>
          <input value={book.author} onChange={(e) => set({ author: e.target.value })} placeholder="Author name" />
        </div>
      </div>

      <label>Genre(s)</label>
      <TagInput value={book.genres} onChange={(g) => set({ genres: g })} placeholder="Add a genre, press Enter" />

      <div className="form-row">
        <div>
          <label>Total pages</label>
          <input type="number" min="0" value={book.totalPages} onChange={(e) => set({ totalPages: e.target.value })} />
        </div>
        <div>
          <label>Format</label>
          <select value={book.format} onChange={(e) => set({ format: e.target.value })}>
            {FORMATS.map((f) => <option key={f} value={f}>{f}</option>)}
          </select>
        </div>
      </div>

      <div className="form-row">
        <div>
          <label>Status</label>
          <select value={book.readStatus} onChange={(e) => set({ readStatus: e.target.value })}>
            {READ_STATUSES.map((s) => <option key={s} value={s}>{s}</option>)}
          </select>
        </div>
        <div>
          <label>Your rating</label>
          <StarRating value={book.rating} onChange={(r) => set({ rating: r })} />
        </div>
      </div>

      <label>Whose book?</label>
      <div className="owner-toggle">
        {OWNERS.map((o) => (
          <button
            key={o}
            type="button"
            className={`owner-btn ${book.owner === o ? "active" : ""}`}
            onClick={() => set({ owner: o })}
          >
            {o}
          </button>
        ))}
      </div>

      <label className="checkbox-row">
        <input type="checkbox" checked={book.isSeries} onChange={(e) => set({ isSeries: e.target.checked })} />
        Part of a series
      </label>
      {book.isSeries && (
        <div className="form-row">
          <div>
            <label>Series name</label>
            <input value={book.seriesName} onChange={(e) => set({ seriesName: e.target.value })} placeholder="e.g. The Broken Earth" />
          </div>
          <div>
            <label>Book #</label>
            <input type="number" min="1" value={book.seriesNumber} onChange={(e) => set({ seriesNumber: e.target.value })} />
          </div>
        </div>
      )}

      <label>Tags</label>
      <TagInput value={book.tags} onChange={(t) => set({ tags: t })} placeholder="favorite, book club, 2026..." />

      <label>Review</label>
      <textarea rows={4} value={book.review} onChange={(e) => set({ review: e.target.value })} placeholder="Your thoughts..." />

      <label className="checkbox-row">
        <input type="checkbox" checked={book.loaned} onChange={(e) => set({ loaned: e.target.checked })} />
        Currently loaned out
      </label>
      {book.loaned && (
        <div className="form-row">
          <div>
            <label>Loaned to</label>
            <input value={book.loanedTo} onChange={(e) => set({ loanedTo: e.target.value })} placeholder="Name" />
          </div>
          <div>
            <label>Date loaned</label>
            <input type="date" value={book.loanedDate} onChange={(e) => set({ loanedDate: e.target.value })} />
          </div>
        </div>
      )}

      <div className="form-actions">
        <button className="btn-text" onClick={onCancel}>Cancel</button>
        <button
          className="btn-primary"
          disabled={!book.title.trim()}
          onClick={() => onSave(book)}
        >
          <Check size={15} /> {isEditing ? "Save changes" : "Add to shelf"}
        </button>
      </div>
    </div>
  );
}

